using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Data.SqlClient;
using System.Security.Cryptography;
using System.Text;

namespace VaultApi.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class SecretsController : ControllerBase
    {
        private static readonly byte[] _encryptionKey = Convert.FromBase64String("K7gNU3sdo+OL0wNhqoVWhr3g6s1xYv72ol/pe/Unols=");
        private static readonly byte[] _signingKey = Convert.FromBase64String("K7gNU3sdo+OL0wNhqoVWhr3g6s1xYv72ol/pe/Unols=");
        private readonly string _connectionString;

        public SecretsController(IConfiguration config)
        {
            _connectionString = config.GetConnectionString("VaultDb");
        }

        [HttpGet("{id}")]
        [Authorize]
        public IActionResult GetSecret(int id)
        {
            using var conn = new SqlConnection(_connectionString);
            conn.Open();
            var cmd = new SqlCommand("SELECT encrypted_value, hmac FROM secrets WHERE id = @id", conn);
            cmd.Parameters.AddWithValue("@id", id);
            using var reader = cmd.ExecuteReader();
            if (!reader.Read()) return NotFound();
            var encrypted = (byte[])reader["encrypted_value"];
            var storedHmac = (byte[])reader["hmac"];
            if (!VerifyHmac(encrypted, storedHmac))
                return StatusCode(500, "Integrity check failed");
            var decrypted = Decrypt(encrypted);
            return Ok(new { value = Encoding.UTF8.GetString(decrypted) });
        }

        [HttpPost]
        [Authorize(Roles = "admin")]
        public IActionResult StoreSecret([FromBody] SecretInput input)
        {
            var encrypted = Encrypt(Encoding.UTF8.GetBytes(input.Value));
            var hmac = ComputeHmac(encrypted);
            using var conn = new SqlConnection(_connectionString);
            conn.Open();
            var cmd = new SqlCommand(
                "INSERT INTO secrets (name, encrypted_value, hmac, created_by) VALUES (@name, @enc, @hmac, @user)", conn);
            cmd.Parameters.AddWithValue("@name", input.Name);
            cmd.Parameters.AddWithValue("@enc", encrypted);
            cmd.Parameters.AddWithValue("@hmac", hmac);
            cmd.Parameters.AddWithValue("@user", User.Identity.Name);
            cmd.ExecuteNonQuery();
            return Created("", null);
        }

        [HttpPut("{id}")]
        [Authorize(Roles = "admin")]
        public IActionResult UpdateSecret(int id, [FromBody] SecretInput input)
        {
            var encrypted = Encrypt(Encoding.UTF8.GetBytes(input.Value));
            var hmac = ComputeHmac(encrypted);
            using var conn = new SqlConnection(_connectionString);
            conn.Open();
            var cmd = new SqlCommand(
                "UPDATE secrets SET encrypted_value = @enc, hmac = @hmac WHERE id = @id", conn);
            cmd.Parameters.AddWithValue("@enc", encrypted);
            cmd.Parameters.AddWithValue("@hmac", hmac);
            cmd.Parameters.AddWithValue("@id", id);
            cmd.ExecuteNonQuery();
            return NoContent();
        }

        private byte[] Encrypt(byte[] plaintext)
        {
            using var aes = Aes.Create();
            aes.Key = _encryptionKey;
            aes.GenerateIV();
            using var encryptor = aes.CreateEncryptor();
            var ct = encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length);
            return aes.IV.Concat(ct).ToArray();
        }

        private byte[] Decrypt(byte[] ciphertext)
        {
            using var aes = Aes.Create();
            aes.Key = _encryptionKey;
            aes.IV = ciphertext.Take(16).ToArray();
            using var decryptor = aes.CreateDecryptor();
            return decryptor.TransformFinalBlock(ciphertext, 16, ciphertext.Length - 16);
        }

        private byte[] ComputeHmac(byte[] data)
        {
            using var hmac = new HMACSHA256(_signingKey);
            return hmac.ComputeHash(data);
        }

        private bool VerifyHmac(byte[] data, byte[] expectedHmac)
        {
            var computed = ComputeHmac(data);
            return CryptographicOperations.FixedTimeEquals(computed, expectedHmac);
        }
    }

    public class SecretInput
    {
        public string Name { get; set; }
        public string Value { get; set; }
    }
}
